enum { BUF_SZ = 4096 };
char buffer[BUF_SZ];
int sock_fd;
ssize_t bytes_read;

// Standard blocking receive
bytes_read = recv(sock_fd, buffer, BUF_SZ, 0);

// Use MSG_DONTWAIT for non-blocking I/O
// bytes_read = recv(sock_fd, buffer, BUF_SZ, MSG_DONTWAIT);

if (bytes_read == -1) {
    // Error handling (check errno for EAGAIN/EWOULDBLOCK)
} else if (bytes_read == 0) {
    // Connection closed by peer
}

/* --- recvfrom (for connectionless sockets) --- */
struct sockaddr src_addr;
socklen_t addr_len = sizeof(src_addr);

bytes_read = recvfrom(sock_fd, buffer, BUF_SZ, 0,
                      &src_addr, &addr_len);
